{id:'test-spotter',name:'Quick Spotter',role:'Spotter',goal:'Report a useful sighting quickly without needing to take custody of the animal.',status:'Test template',version:1,patternIds:[],template:true,behaviours:['Takes a photo or notes distinctive features when safe.','Records the location, direction and time of the sighting.','Shares the sighting with a relevant local channel.'],motivations:['Help an animal get home with a small, immediate action.','Make the sighting useful to someone already searching.'],constraints:['The animal may move away before details can be captured.','The spotter may be commuting, caring for children or unable to stop.'],painPoints:['Not knowing whether the animal is actually lost.','Uncertainty about where a sighting will reach the right person.'],needs:['A very fast reporting flow.','Prompts for the few details that make a sighting actionable.'],history:[]}
