function clone(x){return JSON.parse(JSON.stringify(x))}
let state=load(),view='dashboard',researchType='all',activeSource=null,activePersona=null,pendingDecision=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function load(){try{const x=JSON.parse(localStorage.getItem(KEY)),base=x?.research?{...clone(EMPTY),...x,settings:{...EMPTY.settings,...x.settings},refresh:{...EMPTY.refresh,...x.refresh}}:clone(EMPTY);if(!base.settings.endpoint||base.settings.endpoint==='/api/analyze')base.settings.endpoint=PUBLIC_AI_ENDPOINT;if(base.settings.provider==='OpenAI-compatible')base.settings.provider='OpenAI';for(const p of TEST_PERSONAS){const saved=base.personas.find(x=>x.id===p.id);if(!saved)base.personas.push(clone(p));else if(saved.template)Object.assign(saved,clone(p))}return base}catch{const base=clone(EMPTY);base.personas=clone(TEST_PERSONAS);return base}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}function id(p='id'){return `${p}-${crypto.randomUUID()}`}function now(){return new Date().toISOString()}function day(x){return new Intl.DateTimeFormat('en',{day:'numeric',month:'short',year:'numeric'}).format(new Date(x))}function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function source(i){return state.research.find(x=>x.id===i)}function obs(i){return state.observations.find(x=>x.id===i)}
function empty(title,text,action,label){return `<div class="empty"><b>${esc(title)}</b><p>${esc(text)}</p>${action?`<button class="primary" data-empty="${action}">${esc(label)}</button>`:''}</div>`}
function log(action){state.activity.unshift({id:id('a'),time:now(),action});state.activity=state.activity.slice(0,20)}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function show(sel){$(sel).showModal()}function closeDialogs(){$$('dialog[open]').forEach(x=>x.close())}
function requestText(title,label,initial=''){return new Promise(resolve=>{const dialog=$('#textInputDialog'),form=$('#textInputForm'),input=$('#textInputValue');$('#textInputTitle').textContent=title;$('#textInputLabel').firstChild.textContent=label;input.value=initial;const finish=value=>{form.onsubmit=null;dialog.onclose=null;if(dialog.open)dialog.close();resolve(value)};form.onsubmit=e=>{e.preventDefault();finish(input.value.trim())};dialog.onclose=()=>finish(null);dialog.showModal();requestAnimationFrame(()=>{input.focus();input.select()})})}
function go(name){view=name;$$('.view').forEach(x=>x.classList.remove('active'));$(`#${name}View`).classList.add('active');$$('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===name));location.hash=name;render()}
function render(){counts();dashboard();research();analysis();personas();proposals();gaps();solutions();settingsNotice()}
function counts(){const pending=state.observations.filter(x=>x.status==='pending').length+state.patterns.filter(x=>x.status==='pending').length+state.proposals.filter(x=>x.status==='pending').length+state.gaps.filter(x=>x.status==='pending').length,approvedPatterns=state.patterns.filter(x=>x.status==='approved').length,real=state.personas.filter(x=>!x.template),valid=real.filter(x=>x.status==='Validated').length;$('#navResearch').textContent=state.research.length;$('#navSuggestions').textContent=pending;$('#navPersonas').textContent=state.personas.length;$('#metricResearch').textContent=state.research.length;$('#metricPatterns').textContent=approvedPatterns;$('#metricPersonas').textContent=real.length;$('#metricSuggestions').textContent=pending;$('#pendingPill').textContent=`${pending} pending`;$('#personaBreakdown').textContent=`${valid} validated · ${real.length-valid} unvalidated · ${state.personas.filter(x=>x.template).length} test`}
function dashboard(){const recent=state.research.slice().sort((a,b)=>b.imported.localeCompare(a.imported)).slice(0,3);$('#recentResearch').innerHTML=recent.length?recent.map(researchRow).join(''):empty('No research yet','Import a real source to begin.','add','Add research');const suggestions=[...state.patterns.filter(x=>x.status==='pending').map(x=>({t:'Pattern awaiting review',d:x.title})),...state.observations.filter(x=>x.status==='pending').map(x=>({t:'Evidence awaiting review',d:x.text}))].slice(0,4);$('#dashboardSuggestions').innerHTML=suggestions.length?suggestions.map(x=>`<div class="suggestion-row"><b>${esc(x.t)}</b><small>${esc(x.d)}</small></div>`).join(''):empty('No AI suggestions','Suggestions appear only after real research is analysed.');$('#activityList').innerHTML=state.activity.length?state.activity.slice(0,5).map(x=>`<div class="activity-row"><b>${esc(x.action)}</b><small>${day(x.time)}</small></div>`).join(''):'<div class="meta">No activity yet.</div>';$('#dashboardPersonas').innerHTML=state.personas.length?state.personas.slice(0,5).map(personaCard).join(''):empty('No personas yet','Create a proto-persona or approve evidence first.','persona','Create proto-persona');bindDynamic()}
function researchRow(r){return `<article class="research-card"><div class="source-icon">${r.type==='Interview'?'◉':r.type==='Survey'?'▤':r.type==='Facebook Report'?'f':'⌁'}</div><div><div class="card-title">${esc(r.title)}</div><div>${esc((r.content||r.fileName||'No text preview').slice(0,125))}${(r.content||'').length>125?'…':''}</div><div class="meta">${esc(r.type)} · ${esc(r.participantId||'Unknown')} · imported ${day(r.imported)} · ${r.processed?'analysed':'not analysed'}${r.duplicateStatus==='possible'?' · possible duplicate':''}</div></div><div class="card-actions"><span class="status ${r.processed?'approved':'pending'}">${r.processed?'Analysed':'New'}</span><button class="tiny" data-source="${r.id}">View source</button><button class="tiny" data-edit-source="${r.id}">Edit metadata</button><button class="tiny" data-duplicate="${r.id}">${r.duplicateStatus==='possible'?'Clear duplicate flag':'Mark possible duplicate'}</button></div></article>`}
function research(){const q=$('#researchSearch').value.toLowerCase(),list=state.research.filter(r=>(researchType==='all'||r.type===researchType)&&JSON.stringify(r).toLowerCase().includes(q)),refresh=state.refresh.lastSuccess?`<div class="notice neutral refresh-note">Last on-demand refresh: ${day(state.refresh.lastSuccess)} · ${state.refresh.errors.length} error(s). Original versions are preserved.</div>`:'';$('#researchList').innerHTML=refresh+(list.length?list.sort((a,b)=>b.imported.localeCompare(a.imported)).map(researchRow).join(''):empty('No matching research','Import TXT, CSV, PDF metadata or pasted text.','add','Add research'));bindDynamic()}
function analysis(){const observations=state.observations.slice().sort((a,b)=>b.created.localeCompare(a.created));$('#observationCount').textContent=observations.length;$('#patternCount').textContent=state.patterns.length;$('#observationList').innerHTML=observations.length?observations.map(o=>{const s=source(o.sourceId);return `<article class="observation-card"><span class="status ${o.status}">${o.status}</span><div class="card-title">${esc(o.dimension)}</div><p>${esc(o.text)}</p><div class="excerpt">“${esc(o.excerpt)}”</div><div class="meta">${esc(o.evidenceType)} · Source: ${esc(s?.title||'Missing source')}</div><div class="review-actions">${o.status==='pending'?`<button class="tiny" data-review-observation="${o.id}" data-result="approved">Approve</button><button class="tiny" data-edit-observation="${o.id}">Edit</button><button class="tiny" data-review-observation="${o.id}" data-result="rejected">Reject</button>`:''}<button class="tiny" data-source="${o.sourceId}">Open source</button></div></article>`}).join(''):empty('No observations','Analyse imported research or add a source-linked manual observation.');$('#patternList').innerHTML=state.patterns.length?state.patterns.map(p=>`<details class="pattern-card" open><summary><label class="pattern-select"><input type="checkbox" data-pattern-select="${p.id}"> Select</label><span class="status ${p.status}">${p.status}</span><div class="card-title">${esc(p.title)}</div><p>${esc(p.summary)}</p><div class="meta">${p.observationIds.length} observation${p.observationIds.length===1?'':'s'} · ${new Set(p.observationIds.map(i=>obs(i)?.sourceId)).size} independent source(s)</div></summary><div class="evidence-links">${p.observationIds.map(i=>{const o=obs(i);return o?`<button data-source="${o.sourceId}">${esc(o.excerpt)}</button>`:''}).join('')}</div>${p.status==='pending'?`<div class="review-actions"><button class="tiny" data-review-pattern="${p.id}" data-result="approved">Approve</button><button class="tiny" data-edit-pattern="${p.id}">Edit</button><button class="tiny" data-review-pattern="${p.id}" data-result="rejected">Reject</button></div>`:''}<div class="review-actions">${p.status==='approved'?`<button class="tiny" data-pattern-persona="${p.id}">Create / update persona</button>`:''}${p.observationIds.length>1?`<button class="tiny" data-split-pattern="${p.id}">Split pattern</button>`:''}</div></details>`).join(''):empty('No patterns','Patterns are accepted only when the API returns source-linked observations.');bindDynamic()}
function personaCard(p){const image={Owner:'assets/active-owner-user.png',Finder:'assets/temporary-carer-user-v2.png',Spotter:'assets/quick-spotter-user.png'}[p.role],blank='Not enough evidence yet',rows=[['Main goal',p.goal],['Behaviours',p.behaviours?.join(' · ')],['Motivations',p.motivations?.join(' · ')],['Constraints',p.constraints?.join(' · ')],['Pain points',p.painPoints?.join(' · ')],['Needs',p.needs?.join(' · ')]];return `<article class="persona-card ${p.template?'template-card':''}"><label class="select-persona"><input type="checkbox" data-compare="${p.id}"> Compare</label><div data-persona="${p.id}">${image?`<img src="${image}" alt="Illustrative context, not a research participant">`:`<div class="persona-image">${esc(p.role[0]||'P')}</div>`}<div class="persona-body"><span class="status ${p.template?'test-template':p.status.toLowerCase()}">${p.template?'TEST TEMPLATE':esc(p.status)}</span><h3>${esc(p.name)}</h3><p class="image-note">Illustrative photograph — not a real participant.</p><div class="persona-sections">${rows.map(([k,v])=>`<div><b>${k}</b><span class="${v?'':'missing'}">${esc(v||blank)}</span></div>`).join('')}</div><div class="persona-foot"><span>${esc(p.role)}</span><span>${p.template?'Fills as evidence is approved':`Version ${p.version}`}</span></div></div></div></article>`}
function personas(){$('#personaGrid').innerHTML=state.personas.length?state.personas.map(personaCard).join(''):empty('No personas yet','Start hypothesis-first with an unvalidated proto-persona, or create one from an approved pattern.','persona','Create proto-persona');bindDynamic()}
function comparePersonas(){const ids=$$('[data-compare]:checked').map(x=>x.dataset.compare);if(ids.length<2){toast('Select at least two personas');return}const list=ids.map(i=>state.personas.find(p=>p.id===i));$('#comparisonPanel').innerHTML=`<section class="comparison"><div class="section-label"><h2>Persona comparison</h2><span>${list.length} selected</span></div><div class="compare-table" style="grid-template-columns:150px repeat(${list.length},minmax(150px,1fr))"><b>Attribute</b>${list.map(p=>`<b>${esc(p.name)}</b>`).join('')}<span>Role</span>${list.map(p=>`<div>${esc(p.role)}</div>`).join('')}<span>Main goal</span>${list.map(p=>`<div>${esc(p.goal)}</div>`).join('')}<span>Validation</span>${list.map(p=>`<div>${esc(p.status)}</div>`).join('')}<span>Supporting patterns</span>${list.map(p=>`<div>${(p.patternIds||[]).length}</div>`).join('')}<span>Evidence gaps</span>${list.map(p=>`<div>${(p.patternIds||[]).length?'Review linked patterns':'No linked pattern evidence'}</div>`).join('')}</div></section>`}
function proposals(){const unclassified=state.observations.filter(o=>o.status==='approved'&&!state.patterns.some(p=>p.observationIds.includes(o.id)));$('#proposalSummary').innerHTML=`<b>${unclassified.length} unclassified insight(s).</b> The exploratory threshold is ${state.settings.proposalThreshold} independent cases. A threshold creates a review prompt, never a validated persona.`;$('#proposalList').innerHTML=state.proposals.length?state.proposals.map(p=>`<article class="pattern-card"><span class="status ${p.status}">${p.status}</span><div class="card-title">${esc(p.title)}</div><p>${esc(p.summary)}</p><div class="meta">${p.patternIds.length} supporting pattern(s) · ${p.sourceCount} independent source(s)</div><div class="review-actions">${p.status==='pending'?`<button class="tiny" data-accept-proposal="${p.id}">Create editable draft</button><button class="tiny" data-reject-proposal="${p.id}">Reject</button>`:''}</div></article>`).join(''):empty('No proposed personas','Suggestions appear only when reviewed evidence crosses the exploratory threshold.') ;bindDynamic()}
function assessProposals(){const threshold=Number(state.settings.proposalThreshold)||3;for(const p of state.patterns.filter(x=>x.status==='approved')){const sources=new Set(p.observationIds.map(i=>obs(i)?.sourceId).filter(Boolean));if(sources.size>=threshold&&!state.proposals.some(x=>x.patternIds.includes(p.id))&&!state.personas.some(x=>x.patternIds.includes(p.id)))state.proposals.unshift({id:id('prop'),title:`Potential persona: ${p.title}`,summary:p.summary,patternIds:[p.id],sourceCount:sources.size,status:'pending',created:now()})}log('Assessed unclassified evidence for potential personas');save();render();toast(state.proposals.some(x=>x.status==='pending')?'Proposal review updated':'No threshold-supported persona detected')}
function acceptProposal(pid){const p=state.proposals.find(x=>x.id===pid);p.status='drafted';openPersonaForm(null,state.patterns.find(x=>x.id===p.patternIds[0]));save()}
function rejectProposal(pid){const p=state.proposals.find(x=>x.id===pid);p.status='rejected';log(`Rejected persona proposal: ${p.title}`);save();render()}
function gaps(){$('#gapList').innerHTML=state.gaps.length?state.gaps.map(g=>`<article class="pattern-card"><span class="status ${g.status}">${g.status}</span><div class="card-title">${esc(g.type)} · ${esc(g.title)}</div><p>${esc(g.text)}</p><div class="meta">Supporting patterns: ${g.patternIds.map(i=>esc(state.patterns.find(p=>p.id===i)?.title||'Missing')).join('; ')}</div>${g.status==='pending'?`<div class="review-actions"><button class="tiny" data-review-gap="${g.id}" data-result="approved">Approve</button><button class="tiny" data-review-gap="${g.id}" data-result="rejected">Reject</button></div>`:''}</article>`).join(''):empty('No connections or gaps','Add one only when approved patterns provide supporting evidence.');bindDynamic()}
function openGap(){const approved=state.patterns.filter(x=>x.status==='approved');if(!approved.length){toast('Approve at least one pattern first');return}$('#gapForm').reset();$('#gapPatterns').innerHTML=approved.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('');show('#gapDialog')}
function saveGap(e){e.preventDefault();const title=$('#gapTitle').value.trim(),text=$('#gapText').value.trim(),ids=[...$('#gapPatterns').selectedOptions].map(x=>x.value);if(!title){toast('Add a short descriptive title');$('#gapTitle').focus();return}if(!text){toast('Add an evidence-based interpretation');$('#gapText').focus();return}if(!ids.length){toast('Select at least one supporting approved pattern');$('#gapPatterns').focus();return}state.gaps.unshift({id:id('gap'),type:$('#gapType').value,title,text,patternIds:ids,status:'pending',created:now()});log('Added an evidence-linked gap for review');save();closeDialogs();render();toast('Gap saved for review')}
function solutions(){$('#solutionList').innerHTML=state.solutions.length?state.solutions.map(s=>`<article class="pattern-card"><span class="status ${s.status.toLowerCase().replaceAll(' ','-')}">${esc(s.status)}</span><div class="card-title">${esc(s.title)}</div><p><b>Problem:</b> ${esc(s.problem)}</p><p><b>Hypothesis:</b> ${esc(s.text)}</p><div class="meta">Evidence: ${esc(s.evidenceLabel)}${s.comment?` · Comment: ${esc(s.comment)}`:''}</div><div class="review-actions"><button class="tiny" data-edit-solution="${s.id}">Edit / update status</button></div></article>`).join(''):empty('No solution hypotheses','Add an idea only after an evidence-backed problem or gap is identified.');bindDynamic()}
function openSolution(sid=null){const evidence=[...state.patterns.filter(x=>x.status==='approved').map(x=>({id:`pattern:${x.id}`,label:`Pattern: ${x.title}`})),...state.gaps.filter(x=>x.status==='approved').map(x=>({id:`gap:${x.id}`,label:`Gap: ${x.title}`}))];if(!evidence.length){toast('Approve a pattern or gap first');return}const s=sid?state.solutions.find(x=>x.id===sid):null;$('#solutionForm').reset();$('#solutionForm').dataset.id=sid||'';$('#solutionEvidence').innerHTML=evidence.map(x=>`<option value="${x.id}">${esc(x.label)}</option>`).join('');if(s){$('#solutionTitle').value=s.title;$('#solutionProblem').value=s.problem;$('#solutionText').value=s.text;$('#solutionEvidence').value=s.evidenceId;$('#solutionStatus').value=s.status;$('#solutionComment').value=s.comment||''}show('#solutionDialog')}
function saveSolution(e){e.preventDefault();const eid=$('#solutionEvidence').value,label=$('#solutionEvidence').selectedOptions[0].textContent,data={title:$('#solutionTitle').value.trim(),problem:$('#solutionProblem').value.trim(),text:$('#solutionText').value.trim(),evidenceId:eid,evidenceLabel:label,status:$('#solutionStatus').value,comment:$('#solutionComment').value.trim(),updated:now()},sid=e.target.dataset.id;if(sid)Object.assign(state.solutions.find(x=>x.id===sid),data);else state.solutions.unshift({id:id('sol'),...data,created:now()});log(`${sid?'Updated':'Added'} solution hypothesis: ${data.title}`);save();closeDialogs();render();toast('Solution hypothesis saved')}
async function mergePatterns(){
  const ids=$$('[data-pattern-select]:checked').map(x=>x.dataset.patternSelect),selected=ids.map(i=>state.patterns.find(p=>p.id===i)).filter(Boolean);
  if(selected.length<2){toast('Select at least two patterns');return}
  const sourceTitles=selected.map(pattern=>pattern.title),summaries=[...new Set(selected.map(pattern=>pattern.summary?.trim()).filter(Boolean))].sort((a,b)=>b.length-a.length),patternPayload=selected.map(pattern=>({title:pattern.title,summary:pattern.summary,observations:(pattern.observationIds||[]).map(observationId=>obs(observationId)).filter(Boolean).map(observation=>({dimension:observation.dimension,text:observation.text,excerpt:observation.excerpt,sourceId:observation.sourceId}))}));
  let draft={title:selected[0].title,summary:summaries[0]||selected[0].title},aiMerged=false;
  const mergeButton=$('#mergePatternsSelectedBtn'),controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),30000);
  try{
    mergeButton.disabled=true;mergeButton.textContent='Generating shared pattern…';
    const endpoint=String(state.settings.endpoint||PUBLIC_AI_ENDPOINT).replace(/\/api\/analyze\/?$/,'/api/merge-patterns'),response=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({patterns:patternPayload}),signal:controller.signal}),data=await response.json().catch(()=>({}));
    if(response.ok&&data.pattern?.title&&data.pattern?.summary){draft=data.pattern;aiMerged=true}
  }catch(error){/* The researcher can still complete the merge manually when the AI backend is unavailable. */}
  finally{clearTimeout(timeout);mergeButton.disabled=false;mergeButton.textContent='Merge selected patterns'}
  const title=await requestText('Review merged pattern','Complete shared pattern title',draft.title);
  if(!title?.trim())return;
  let summary=await requestText('Review merged pattern','Complete pattern statement — no ellipsis or truncated text',draft.summary);
  while(summary&&(!/[.!?]$/.test(summary.trim())||/(?:\.{3}|…)$/.test(summary.trim()))){toast('Write one complete sentence ending with . ! or ?');summary=await requestText('Complete the pattern statement','The sentence must be complete and must not end with an ellipsis',summary.replace(/(?:\.{3}|…)$/,'').trim())}
  if(!summary?.trim())return;
  const canonical=selected[0],absorbedIds=ids.filter(patternId=>patternId!==canonical.id);
  const affectedPersonaIds=[...new Set(state.personas.filter(persona=>!persona.template&&(persona.patternIds||[]).some(patternId=>ids.includes(patternId))).map(persona=>persona.id))];
  Object.assign(canonical,{title:title.trim(),summary:summary.trim(),observationIds:[...new Set(selected.flatMap(pattern=>pattern.observationIds||[]))],status:'pending',reviewState:'edited',updated:now(),origin:'researcher merge',affectedPersonaIds});
  canonical.history=Array.isArray(canonical.history)?canonical.history:canonical.history?[canonical.history]:[];
  canonical.history.unshift({action:'merge',at:now(),sourcePatternIds:ids,sourceTitles,sourceSummaries:summaries,aiRegenerated:aiMerged});
  state.patterns=state.patterns.filter(pattern=>!absorbedIds.includes(pattern.id));
  const replaceIds=list=>[...new Set((list||[]).map(patternId=>ids.includes(patternId)?canonical.id:patternId))];
  state.personas.forEach(persona=>{persona.patternIds=replaceIds(persona.patternIds)});
  state.personaUpdates.forEach(update=>{update.patternIds=replaceIds(update.patternIds)});
  state.proposals.forEach(proposal=>{proposal.patternIds=replaceIds(proposal.patternIds)});
  state.gaps.forEach(gap=>{gap.patternIds=replaceIds(gap.patternIds)});
  state.solutions.forEach(solution=>{if(ids.some(patternId=>solution.evidenceId===`pattern:${patternId}`)){solution.evidenceId=`pattern:${canonical.id}`;solution.evidenceLabel=`Pattern: ${canonical.title}`}});
  log(`Merged ${selected.length} patterns into one grouped pattern for review: ${canonical.title}`);save();render();toast(`One merged pattern created — review and approve it next`)
}
function splitPattern(pid){const p=state.patterns.find(x=>x.id===pid);if(p.observationIds.length<2)return;state.patterns=state.patterns.filter(x=>x.id!==pid);for(const oid of p.observationIds){const o=obs(oid);state.patterns.unshift({id:id('pat'),title:`${o.dimension}: ${o.text.slice(0,58)}`,summary:o.text,observationIds:[oid],status:'pending',created:now(),origin:'researcher split',history:{action:'split',sourcePatternId:pid}})}log(`Split pattern: ${p.title}`);save();render()}
function settingsNotice(){const configured=state.settings.endpoint&&state.settings.endpoint!=='/api/analyze';$('#aiConfigNotice').className=`notice ${configured?'ok':''}`;$('#aiConfigNotice').innerHTML=configured?`Analysis will call <b>${esc(state.settings.provider)}</b> through the configured secure backend. Results still require review.`:'<b>AI backend not configured for this hosted prototype.</b> Import and manual evidence review work now. Set a backend endpoint in Settings; API keys must remain server-side.'}
function updatePatternSelection(){const selected=$$('[data-pattern-select]:checked'),bar=$('#patternSelectionBar'),button=$('#mergePatternsSelectedBtn');if(!bar||!button)return;bar.hidden=!selected.length;$('#selectedPatternCount').textContent=selected.length;button.disabled=selected.length<2;$('#patternSelectionHint').textContent=selected.length<2?'Select at least one more pattern.':'Merge the selected cards into one reviewable pattern.'}
function bindDynamic(){$$('[data-empty="add"]').forEach(x=>x.onclick=openResearch);$$('[data-empty="persona"]').forEach(x=>x.onclick=()=>openPersonaForm());$$('[data-source]').forEach(x=>x.onclick=()=>openSource(x.dataset.source));$$('[data-edit-source]').forEach(x=>x.onclick=()=>editSource(x.dataset.editSource));$$('[data-duplicate]').forEach(x=>x.onclick=()=>toggleDuplicate(x.dataset.duplicate));$$('[data-persona]').forEach(x=>x.onclick=()=>openPersonaDetails(x.dataset.persona));$$('[data-review-observation]').forEach(x=>x.onclick=()=>decision('observation',x.dataset.reviewObservation,x.dataset.result));$$('[data-review-pattern]').forEach(x=>x.onclick=()=>decision('pattern',x.dataset.reviewPattern,x.dataset.result));$$('[data-review-gap]').forEach(x=>x.onclick=()=>decision('gap',x.dataset.reviewGap,x.dataset.result));$$('[data-edit-observation]').forEach(x=>x.onclick=()=>editObservation(x.dataset.editObservation));$$('[data-edit-pattern]').forEach(x=>x.onclick=()=>editPattern(x.dataset.editPattern));$$('[data-pattern-persona]').forEach(x=>x.onclick=()=>personaFromPattern(x.dataset.patternPersona));$$('[data-split-pattern]').forEach(x=>x.onclick=()=>splitPattern(x.dataset.splitPattern));$$('[data-accept-proposal]').forEach(x=>x.onclick=()=>acceptProposal(x.dataset.acceptProposal));$$('[data-reject-proposal]').forEach(x=>x.onclick=()=>rejectProposal(x.dataset.rejectProposal));$$('[data-edit-solution]').forEach(x=>x.onclick=()=>openSolution(x.dataset.editSolution));$$('[data-pattern-select]').forEach(x=>x.onchange=updatePatternSelection);updatePatternSelection()}
function openResearch(){$('#researchForm').reset();$('#sourceDate').value=new Date().toISOString().slice(0,10);show('#researchDialog')}
async function saveResearch(e){e.preventDefault();const f=$('#sourceFile').files[0];let content=$('#sourceContent').value.trim(),fileData=null;if(f){if(f.size>1500000){toast('File is too large for browser storage (1.5 MB max)');return}if(f.type==='application/pdf'){fileData=await fileToData(f);if(!content)content='PDF attached. Paste an excerpt for browser preview, or use the configured backend for extraction.'}else if(!content)content=await f.text()}if(!content&&!f){toast('Add pasted content or a file');return}const base={type:$('#sourceType').value,title:$('#sourceTitle').value.trim(),date:$('#sourceDate').value||'Unknown',participantId:$('#participantId').value.trim()||'Unknown',participantRole:$('#participantRole').value,url:$('#sourceUrl').value.trim()||'',fileName:f?.name||'',fileType:f?.type||'',fileData,imported:now(),processed:false},parts=$('#bulkMode').checked?content.split(/^---\s*$/m).map(x=>x.trim()).filter(Boolean):[content];parts.forEach((part,i)=>state.research.unshift({id:id('src'),...base,title:parts.length>1?`${base.title} · ${i+1}`:base.title,participantId:parts.length>1?`${base.participantId}-${i+1}`:base.participantId,content:part,duplicateStatus:'unchecked'}));log(`Added ${parts.length} research source${parts.length===1?'':'s'}`);save();closeDialogs();render();go('research');toast(`${parts.length} original source${parts.length===1?'':'s'} saved`)}
async function fetchPublicUrl(){const url=$('#sourceUrl').value.trim();if(!url){toast('Add a public source URL first');return}const endpoint=(state.settings.endpoint||'/api/analyze').replace(/\/api\/analyze\/?$/,'/api/import-url');try{$('#fetchUrlBtn').disabled=true;$('#fetchUrlBtn').textContent='Attempting access…';const res=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url})}),data=await res.json();if(!res.ok)throw new Error(data.error||`Import returned ${res.status}`);$('#sourceContent').value=data.content||'';if(!$('#sourceTitle').value)$('#sourceTitle').value=data.title||'Imported public source';toast('Review extracted content before saving')}catch(err){toast(`Automatic extraction unavailable: ${err.message}. Use manual import.`)}finally{$('#fetchUrlBtn').disabled=false;$('#fetchUrlBtn').textContent='Attempt public URL extraction'}}
async function refreshSources(){const urls=state.research.filter(x=>x.url);if(!urls.length){go('research');toast('No URL sources to refresh. Add a source manually.');return}const endpoint=(state.settings.endpoint||'/api/analyze').replace(/\/api\/analyze\/?$/,'/api/import-url');state.refresh.errors=[];let changed=0;for(const r of urls){try{const res=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url:r.url})}),data=await res.json();if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);if(data.content&&data.content!==r.content){r.previousContents??=[];r.previousContents.unshift({content:r.content,at:now()});r.content=data.content;r.processed=false;r.refreshed=now();changed++}}catch(err){state.refresh.errors.push({sourceId:r.id,message:err.message,at:now()})}}state.refresh.lastSuccess=now();log(`On-demand refresh completed: ${changed} changed source(s)`);save();render();go('research');toast(`Refresh complete: ${changed} changed, ${state.refresh.errors.length} error(s)`)}
function fileToData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function openSource(sid){const r=source(sid);if(!r)return;activeSource=sid;$('#sourceDialogTitle').textContent=r.title;$('#sourceDialogBody').innerHTML=`<div><span class="status ${r.processed?'approved':'pending'}">${r.processed?'Analysed':'Not analysed'}</span><p class="meta">${esc(r.type)} · ${esc(r.participantId)} · role ${esc(r.participantRole)} · ${esc(r.date)}</p>${r.url?`<p><a href="${esc(r.url)}" target="_blank" rel="noreferrer">Open original webpage ↗</a></p>`:''}<div class="source-original">${esc(r.content||'Binary PDF attached; no text preview.')}</div>${r.fileName?`<p class="meta">Attachment: ${esc(r.fileName)}</p>`:''}</div>`;show('#sourceDialog')}
function openObservation(){closeDialogs();$('#observationForm').reset();$('#observationSourceId').value=activeSource;show('#observationDialog')}
function saveObservation(e){e.preventDefault();const o={id:id('obs'),sourceId:$('#observationSourceId').value,dimension:$('#observationDimension').value,text:$('#observationText').value.trim(),excerpt:$('#observationExcerpt').value.trim(),evidenceType:$('#observationEvidenceType').value,status:'pending',origin:'manual',created:now(),reviewNote:''};state.observations.unshift(o);log('Added a source-linked observation for review');save();closeDialogs();render();go('analysis');toast('Observation saved for review')}
function decision(kind,target,result){const list=kind==='pattern'?state.patterns:kind==='gap'?state.gaps:state.observations,item=list.find(x=>x.id===target);pendingDecision={kind,target,result};$('#confirmTitle').textContent=`${result==='approved'?'Approve':'Reject'} ${kind}`;$('#confirmText').textContent=kind==='observation'?item.text:item.title;$('#confirmNote').value='';show('#confirmDialog')}
function confirmDecision(){const note=$('#confirmNote').value.trim();if(!note){toast('Add a review note');return}const list=pendingDecision.kind==='pattern'?state.patterns:pendingDecision.kind==='gap'?state.gaps:state.observations,item=list.find(x=>x.id===pendingDecision.target);item.status=pendingDecision.result;item.reviewState=pendingDecision.result;item.reviewNote=note;item.reviewed=now();log(`${pendingDecision.result==='approved'?'Approved':'Rejected'} ${pendingDecision.kind}: ${item.title||item.text}`);if(pendingDecision.kind==='observation'&&pendingDecision.result==='approved')groupApprovedObservations();if(pendingDecision.kind==='pattern'&&pendingDecision.result==='approved'&&item.origin==='researcher merge'&&item.affectedPersonaIds?.length){state.personaUpdates??=[];item.affectedPersonaIds.forEach(personaId=>{let update=state.personaUpdates.find(candidate=>candidate.personaId===personaId&&candidate.status==='pending');if(!update){update={id:id('update'),personaId,patternIds:[],status:'pending',created:now()};state.personaUpdates.unshift(update)}update.patternIds=[...new Set([...update.patternIds,item.id])];update.updated=now()});item.affectedPersonaIds=[]}save();closeDialogs();render();toast(pendingDecision.kind==='pattern'&&pendingDecision.result==='approved'&&item.origin==='researcher merge'?'Merged pattern approved; linked personas are ready for re-synthesis.':'Review decision recorded')}
function groupApprovedObservations(){const approved=state.observations.filter(x=>x.status==='approved');for(const o of approved){if(state.patterns.some(p=>p.observationIds.includes(o.id)))continue;state.patterns.unshift({id:id('pat'),title:`${o.dimension}: ${o.text.slice(0,58)}`,summary:o.text,observationIds:[o.id],status:'pending',created:now(),origin:'researcher-reviewed evidence'})}}
async function editObservation(oid){const o=obs(oid),text=await requestText('Edit observation','Interpretation (the source excerpt remains unchanged)',o.text);if(text?.trim()){o.text=text.trim();o.status='pending';o.reviewState='edited';o.updated=now();log('Edited an observation interpretation');save();render()}}
async function editPattern(pid){const p=state.patterns.find(x=>x.id===pid),text=await requestText('Edit pattern','Pattern title',p.title);if(text?.trim()){p.title=text.trim();p.status='pending';p.reviewState='edited';p.updated=now();log('Edited a behavioural pattern');save();render()}}
function editSource(sid){openResearch(sid)}
function toggleDuplicate(sid){const r=source(sid);r.duplicateStatus=r.duplicateStatus==='possible'?'unchecked':'possible';log(`${r.duplicateStatus==='possible'?'Flagged':'Cleared'} possible duplicate: ${r.title}`);save();render()}
function personaFromPattern(pid){const p=state.patterns.find(x=>x.id===pid);openPersonaForm(null,p)}
function openPersonaDetails(pid){const p=state.personas.find(x=>x.id===pid);if(!p)return;activePersona=pid;const image={Owner:'assets/active-owner-user.png',Finder:'assets/temporary-carer-user-v2.png',Spotter:'assets/quick-spotter-user.png'}[p.role],blank='Not enough evidence yet',sections=[['◎','Main goal',p.goal?[p.goal]:[]],['♙','Behaviours',p.behaviours||[]],['♡','Motivations',p.motivations||[]],['△','Constraints',p.constraints||[]],['ϟ','Pain points',p.painPoints||[]],['☆','Needs',p.needs||[]]];$('#personaViewContent').innerHTML=`${image?`<div class="persona-view-visual"><img class="persona-view-image" src="${image}" alt="Illustrative context, not a research participant"></div>`:''}<div class="persona-view-sheet"><div class="persona-view-heading"><span class="eyebrow">PERSONA PROFILE</span><div class="persona-view-titleline"><h2>${esc(p.name)}</h2><span class="status ${p.template?'test-template':p.status.toLowerCase()}">${p.template?'TEST TEMPLATE':esc(p.status)}</span></div><p>${esc(p.role)} · ${p.template?'Demonstration content — not research findings':`Version ${p.version}`}</p></div><div class="persona-view-sections">${sections.map(([icon,title,items])=>`<details><summary><span class="persona-section-icon" aria-hidden="true">${icon}</span><div><h3>${title}</h3><p class="persona-section-preview ${items.length?'':'missing'}">${esc(items[0]||blank)}</p></div><span class="persona-section-arrow" aria-hidden="true">›</span></summary><div class="persona-section-detail">${items.length?`<ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:`<p class="missing">${blank}</p>`}</div></details>`).join('')}</div><div class="persona-view-note">${p.template?'Demonstration content only. It illustrates how a completed persona may look and is not supported by uploaded research.':`${(p.patternIds||[]).length} supporting pattern(s) linked to this persona.`}</div></div>`;show('#personaViewDialog');$('#personaViewDialog').scrollTop=0}
function lines(value){return value.split(/\n+/).map(x=>x.trim()).filter(Boolean)}
function openPersonaForm(pid=null,pattern=null){closeDialogs();$('#personaForm').reset();$('#personaId').value=pid||'';$('#personaDialogTitle').textContent=pid?'Update persona':'Create proto-persona';$('#personaHistory').innerHTML='';if(pid){const p=state.personas.find(x=>x.id===pid);$('#personaDialogTitle').textContent=p.template?'Complete test template':'Update persona';$('#personaName').value=p.name;$('#personaRole').value=p.role;$('#personaGoal').value=p.goal;$('#personaBehaviours').value=(p.behaviours||[]).join('\n');$('#personaMotivations').value=(p.motivations||[]).join('\n');$('#personaConstraints').value=(p.constraints||[]).join('\n');$('#personaPainPoints').value=(p.painPoints||[]).join('\n');$('#personaNeeds').value=(p.needs||[]).join('\n');$('#personaStatus').value=p.template?'Unvalidated':p.status;$('#personaReason').placeholder=p.template?'Cite the new research that supports completing this test template.':'What new research supports this change?';$('#personaHistory').innerHTML=p.history?.length?`<b>Version history</b><ol>${p.history.map(h=>`<li>Version ${h.version} · ${day(h.changed)} · ${esc(h.origin)}<br>${esc(h.reason)}</li>`).join('')}</ol>`:'<div class="notice neutral">Test template only. It contains no research findings yet.</div>'}else if(pattern){$('#personaGoal').value=pattern.summary;$('#personaReason').value=`Created from approved pattern: ${pattern.title}`;$('#personaForm').dataset.pattern=pattern.id}else delete $('#personaForm').dataset.pattern;show('#personaDialog')}
function savePersona(e){e.preventDefault();const pid=$('#personaId').value,patternId=e.target.dataset.pattern||null,record={name:$('#personaName').value.trim(),role:$('#personaRole').value.trim(),goal:$('#personaGoal').value.trim(),behaviours:lines($('#personaBehaviours').value),motivations:lines($('#personaMotivations').value),constraints:lines($('#personaConstraints').value),painPoints:lines($('#personaPainPoints').value),needs:lines($('#personaNeeds').value),status:$('#personaStatus').value},reason=$('#personaReason').value.trim();if(pid){const p=state.personas.find(x=>x.id===pid);p.history??=[];p.history.unshift({version:p.version,values:{name:p.name,role:p.role,goal:p.goal,status:p.status,behaviours:p.behaviours||[],motivations:p.motivations||[],constraints:p.constraints||[],painPoints:p.painPoints||[],needs:p.needs||[]},reason,changed:now(),origin:'manual'});Object.assign(p,record,{template:false,version:p.version+1,updated:now()});log(`Updated persona: ${p.name}`)}else{state.personas.unshift({id:id('per'),...record,template:false,version:1,patternIds:patternId?[patternId]:[],history:[{version:1,values:record,reason,changed:now(),origin:patternId?'approved pattern':'manual hypothesis'}],created:now(),updated:now()});log(`Created persona: ${record.name}`)}save();closeDialogs();render();go('personas');toast('Persona version saved')}
async function analyse(){const pending=state.research.filter(x=>!x.processed);if(!pending.length){toast('No unprocessed research sources');return}const endpoint=state.settings.endpoint;if(!endpoint){toast('Configure an analysis backend in Settings');return}$('#analyseBtn').disabled=true;$('#analyseBtn').textContent='Analysing…';try{const res=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({project:{name:'Lost & Found Pets',location:'Lisbon, Portugal'},provider:state.settings.provider,model:state.settings.model,sources:pending.map(({fileData,...r})=>r)})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||`Backend returned ${res.status}`);if(!Array.isArray(data.observations))throw new Error('Backend response did not include observations');const keyToId=new Map();for(const raw of data.observations){const s=source(raw.sourceId);if(!s||!raw.excerpt||!s.content.includes(raw.excerpt))continue;const observationId=id('obs');keyToId.set(raw.key,observationId);state.observations.unshift({id:observationId,sourceId:s.id,dimension:raw.dimension||'Unknown',text:raw.text,excerpt:raw.excerpt,evidenceType:raw.evidenceType==='Interpretation'?'Interpretation':'Direct observation',status:'pending',origin:'AI',created:now(),reviewNote:''})}for(const p of data.patterns||[]){const ids=(p.observationKeys||[]).map(key=>keyToId.get(key)).filter(Boolean),counterEvidenceIds=(p.counterEvidenceKeys||[]).map(key=>keyToId.get(key)).filter(Boolean),independentSources=new Set(ids.map(i=>obs(i)?.sourceId));if(ids.length>=2&&independentSources.size>=2)state.patterns.unshift({id:id('pat'),title:p.title,summary:p.summary,observationIds:ids,counterEvidenceIds,status:'pending',created:now(),origin:'AI grouping',history:[{action:'AI grouping',at:now(),observationIds:[...ids]}]})}pending.forEach(x=>x.processed=true);log(`AI analysed ${pending.length} source(s) and proposed ${keyToId.size} observation(s)`);save();render();toast('AI suggestions are ready for human review')}catch(err){toast(`Analysis unavailable: ${err.message}`);$('#aiConfigNotice').className='notice';$('#aiConfigNotice').innerHTML=`<b>Analysis failed honestly—no findings were created.</b> ${esc(err.message)}`}finally{$('#analyseBtn').disabled=false;$('#analyseBtn').textContent='✦ Analyse unprocessed research'}}
function openSettings(){$('#apiEndpoint').value=state.settings.endpoint;$('#apiProvider').value=state.settings.provider;$('#apiModel').value=state.settings.model;show('#settingsDialog')}
function saveSettings(e){e.preventDefault();state.settings={...state.settings,endpoint:$('#apiEndpoint').value.trim(),provider:$('#apiProvider').value.trim()||'Backend provider',model:$('#apiModel').value.trim()||'Backend configured'};save();closeDialogs();render();toast('Backend settings saved')}
$$('#nav button').forEach(x=>x.onclick=()=>go(x.dataset.view));$$('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));$$('.close').forEach(x=>x.onclick=closeDialogs);$('#quickAdd').onclick=$('#addResearchBtn').onclick=openResearch;$('#quickRefresh').onclick=refreshSources;$('#newPersonaBtn').onclick=()=>openPersonaForm();$('#compareBtn').onclick=comparePersonas;$('#assessProposalsBtn').onclick=assessProposals;$('#newGapBtn').onclick=openGap;$('#newSolutionBtn').onclick=()=>openSolution();$('#mergePatternsBtn').onclick=mergePatterns;$('#mergePatternsSelectedBtn').onclick=mergePatterns;$('#clearPatternSelectionBtn').onclick=()=>{$$('[data-pattern-select]').forEach(box=>box.checked=false);updatePatternSelection()};$('#settingsBtn').onclick=openSettings;$('#helpBtn').onclick=()=>toast('Start with Research Data → Add Research Data');$('#manualObservationBtn').onclick=openObservation;$('#editPersonaBtn').onclick=()=>openPersonaForm(activePersona);$('#analyseBtn').onclick=analyse;$('#fetchUrlBtn').onclick=fetchPublicUrl;$('#researchForm').onsubmit=saveResearch;$('#observationForm').onsubmit=saveObservation;$('#personaForm').onsubmit=savePersona;$('#gapForm').onsubmit=saveGap;$('#solutionForm').onsubmit=saveSolution;$('#settingsForm').onsubmit=saveSettings;$('#confirmAction').onclick=confirmDecision;$('#researchSearch').oninput=research;$('#globalSearch').oninput=e=>{$('#researchSearch').value=e.target.value;go('research')};$$('#researchTabs button').forEach(x=>x.onclick=()=>{$$('#researchTabs button').forEach(b=>b.classList.remove('active'));x.classList.add('active');researchType=x.dataset.type;research()});window.onhashchange=()=>{const h=location.hash.slice(1);if($(`#${h}View`))go(h)};go(location.hash.slice(1)||'dashboard');
